#!/usr/bin/env node
// Patches the Capacitor-generated android/app/build.gradle with a release
// signingConfig that reads credentials from environment variables. Idempotent.
//
// android/ is gitignored and regenerated by `npx cap add android` on each CI
// run, so the signing config has to be re-injected each build rather than
// committed.

import { readFileSync, writeFileSync, existsSync } from "node:fs";

const gradlePath = "android/app/build.gradle";

if (!existsSync(gradlePath)) {
  console.error(`Missing ${gradlePath}. Run 'npx cap add android' first.`);
  process.exit(1);
}

let text = readFileSync(gradlePath, "utf8");

if (text.includes("signingConfigs")) {
  console.log("signingConfig already present, skipping.");
  process.exit(0);
}

const signingBlock = `
    signingConfigs {
        release {
            storeFile file(System.getenv('KEYSTORE_PATH') ?: 'release.keystore')
            storePassword System.getenv('KEYSTORE_PASSWORD')
            keyAlias System.getenv('KEY_ALIAS')
            keyPassword System.getenv('KEY_PASSWORD')
        }
    }
`;

const androidOpen = /(android\s*\{\s*\n)/;
if (!androidOpen.test(text)) {
  console.error('Could not locate "android {" block in build.gradle.');
  process.exit(1);
}
text = text.replace(androidOpen, `$1${signingBlock}`);

const releaseOpen = /(buildTypes\s*\{\s*\n\s*release\s*\{\s*\n)/;
if (!releaseOpen.test(text)) {
  console.error('Could not locate "buildTypes { release {" block in build.gradle.');
  process.exit(1);
}
text = text.replace(releaseOpen, `$1            signingConfig signingConfigs.release\n`);

writeFileSync(gradlePath, text);
console.log(`Patched ${gradlePath} with release signing config.`);
